#!/usr/bin/env python3
"""news-image-20261117 V2 entry program (stdlib only).

Writes the finished 1024x1024 front-page PNG to
$MAKEFUN_OUTPUT_DIR/entry.png (fallback: /output/entry.png if /output
exists, else output/entry.png). Deterministic, no network, no randomness.
"""
import base64
import os
import zlib

DATA = (
    "",
    "",
    "",
    "",
    "",
)


def main():
    raw = zlib.decompress(base64.b64decode("".join(DATA)))
    outdir = os.environ.get("MAKEFUN_OUTPUT_DIR")
    if not outdir:
        outdir = "/output" if os.path.isdir("/output") else "output"
    os.makedirs(outdir, exist_ok=True)
    path = os.path.join(outdir, "entry.png")
    with open(path, "wb") as f:
        f.write(raw)
    print("wrote", path, len(raw), "bytes")


if __name__ == "__main__":
    main()
